    public bool IsAboveZero() => _si > 0;
    public bool IsBelowZero() => _si < 0;
    /// <summary>Not NaN and not infinite, like EngineeringUnits.</summary>
    public bool HasValue() => !double.IsNaN(_si) && !double.IsInfinity(_si);
    public bool HasNoValue() => !HasValue();
    /// <summary>A ForcePerLength is never null - returns itself. The ForcePerLength? version returns Zero for null.</summary>
    public ForcePerLength IfNullSetToZero() => this;
    public static ForcePerLength Min(ForcePerLength a, ForcePerLength b) => a._si <= b._si ? a : b;
    public static ForcePerLength Max(ForcePerLength a, ForcePerLength b) => a._si >= b._si ? a : b;
    /// <summary>
    /// == with your own tolerance. == itself already allows 1e-12 (relative), so 1 ft == 12 in is true
    /// even though the doubles differ in the last bit.
    /// </summary>
    public bool IsCloseTo(ForcePerLength other, double relativeTolerance = SIComparison.RelativeTolerance)
        => SIComparison.Equal(_si, other._si, relativeTolerance);
    public bool IsNaN() => double.IsNaN(_si);
    public bool IsInfinity() => double.IsInfinity(_si);

    // ---- Equality ----
    public bool Equals(ForcePerLength other) => _si.Equals(other._si);
    public override bool Equals(object? obj) => obj is ForcePerLength other && Equals(other);
    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(ForcePerLength other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is ForcePerLength other ? CompareTo(other) : throw new ArgumentException($"Can't compare ForcePerLength with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, ForcePerLengthUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(ForcePerLengthUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to ForcePerLength, but math on it needs the ForcePerLength first.
    /// </summary>
    public QuantityInUnit<ForcePerLength> ToUnit(ForcePerLengthUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public ForcePerLength ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "N/m"}. Reads that (any unit of ForcePerLength, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class ForcePerLengthJsonConverter : JsonConverter<ForcePerLength>
{
    public override ForcePerLength Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => ForcePerLength.FromSI(QuantityJson.Read(ref reader, "ForcePerLength", ForcePerLengthUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, ForcePerLength value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, ForcePerLengthUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this ForcePerLength value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this ForcePerLength value) => new(Math.Sqrt(value.SI));

    public static ForcePerLength Sum(this IEnumerable<ForcePerLength> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return ForcePerLength.FromSI(sum);
    }

    public static ForcePerLength Average(this IEnumerable<ForcePerLength> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : ForcePerLength.FromSI(sum / count);
    }

    public static ForcePerLength Min(this IEnumerable<ForcePerLength> values) => Aggregate(values, Math.Min);
    public static ForcePerLength Max(this IEnumerable<ForcePerLength> values) => Aggregate(values, Math.Max);

    private static ForcePerLength Aggregate(IEnumerable<ForcePerLength> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return ForcePerLength.FromSI(result);
    }
}
